    } else {
      // Fallback capsule
      const geo = new THREE.CapsuleGeometry(0.4, 1.2, 8, 16);
      const mat = new THREE.MeshStandardMaterial({
        color: this.teamId === 0 ? 0xf97316 : 0x38bdf8,
