      this.money -= ECONOMY.vestPrice;
      this.armor = 100;
    }
    if (this.money >= WEAPONS.rifle.price && !this.loadout.primary) {
      this.money -= WEAPONS.rifle.price;
      this.loadout.primary = { ...WEAPONS.rifle, ammo: WEAPONS.rifle.mag, reserve: WEAPONS.rifle.reserve };
